function validate([mat]) {
  if (!Array.isArray(mat) || mat.length < 1 || mat.length > 500) return 'mat needs 1 to 500 rows.';
  const n = mat[0].length;
  if (n < 1 || n > 500) return 'Each row needs 1 to 500 values.';
  for (const row of mat) {
    if (row.length !== n) return 'Every row must have the same length.';
    for (let c = 0; c < n; c++) {
      if (!Number.isInteger(row[c]) || row[c] < 1 || row[c] > 10000) return 'Each value is an integer from 1 to 10000.';
      if (c > 0 && row[c] <= row[c - 1]) return 'Each row must be strictly increasing.';
    }
  }
  return null;
}

