function smallestCommonElement(mat) {
  const rows = mat.length;
  const count = new Array(10001).fill(0);

  for (const row of mat) {
    for (const value of row) {
      count[value]++;
    }
  }

  for (const value of mat[0]) {
    if (count[value] === rows) {
      return value;
    }
  }
  return -1;
}

