function generate(rand, size) {
  const large = size === 'large';
  const m = large ? 60 + Math.floor(rand() * 41) : 1 + Math.floor(rand() * 4);
  const n = large ? 60 + Math.floor(rand() * 41) : 1 + Math.floor(rand() * 5);
  const top = large ? 10000 : 12;
  // A few shared values are planted in every row so that most inputs have an answer.
  const shared = new Set();
  const wanted = Math.floor(rand() * Math.min(n, 4));
  while (shared.size < wanted) shared.add(1 + Math.floor(rand() * top));
  const mat = [];
  for (let r = 0; r < m; r++) {
    const row = new Set(shared);
    while (row.size < n) row.add(1 + Math.floor(rand() * top));
    mat.push([...row].sort((a, b) => a - b));
  }
  return [mat];
}
